package io.sensible.studio.wcm.impl.msm;

import java.io.File;
import java.util.LinkedHashMap;
import java.util.Map;

import javax.xml.parsers.DocumentBuilderFactory;

import org.apache.sling.testing.mock.sling.ResourceResolverType;
import org.apache.sling.testing.mock.sling.junit5.SlingContext;
import org.w3c.dom.Attr;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.NamedNodeMap;
import org.w3c.dom.Node;

/**
 * Test setup: the WKND MSM fixture (generated by {@code tools/observe_msm.py} from the WKND sample content) at
 * {@code /content}, Sensible Studio's rollout configurations read from the {@code studio-msm-content} package sources, and the MSM
 * services.
 */
final class MsmTestSupport {

    static final String PACKAGE = "../studio-compat-content/studio-msm-content/jcr_root/libs/msm/wcm/rolloutconfigs/.content.xml";
    static final String BLUEPRINT = "/content/wknd/language-masters/en";
    static final String US = "/content/wknd/us/en";
    static final String CA = "/content/wknd/ca/en";

    private MsmTestSupport() {
    }

    static SlingContext newContext() {
        return new SlingContext(ResourceResolverType.RESOURCERESOLVER_MOCK);
    }

    static final class Services {
        RolloutConfigManagerImpl configs;
        LiveRelationshipManagerImpl relationships;
        RolloutManagerImpl rollouts;
    }

    static Services setUp(SlingContext context) throws Exception {
        context.load().json("/msm/wknd-msm-content.json", "/content");
        loadDocview(context, new File(PACKAGE), "/libs/msm/wcm/rolloutconfigs");
        Services s = new Services();
        s.configs = context.registerInjectActivateService(new RolloutConfigManagerImpl());
        s.relationships = context.registerInjectActivateService(new LiveRelationshipManagerImpl());
        s.rollouts = context.registerInjectActivateService(new RolloutManagerImpl());
        return s;
    }

    /** Creates the nodes of a FileVault docview file (string properties and {@code {Boolean}} only). */
    static void loadDocview(SlingContext context, File file, String path) throws Exception {
        DocumentBuilderFactory f = DocumentBuilderFactory.newInstance();
        f.setNamespaceAware(true);
        Document doc = f.newDocumentBuilder().parse(file);
        create(context, doc.getDocumentElement(), path);
    }

    private static void create(SlingContext context, Element el, String path) {
        Map<String, Object> props = new LinkedHashMap<>();
        NamedNodeMap attrs = el.getAttributes();
        for (int i = 0; i < attrs.getLength(); i++) {
            Attr a = (Attr) attrs.item(i);
            if (a.getName().startsWith("xmlns")) {
                continue;
            }
            String v = a.getValue();
            props.put(a.getName(), v.startsWith("{Boolean}") ? Boolean.valueOf(v.substring(9)) : v);
        }
        context.create().resource(path, props);
        for (Node n = el.getFirstChild(); n != null; n = n.getNextSibling()) {
            if (n instanceof Element) {
                create(context, (Element) n, path + "/" + ((Element) n).getTagName());
            }
        }
    }
}
